        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var finalOci = last.results ? last.results.oci : 45;
            var finalCompliance = last.results ? last.results.compliance : 40;
            var finalRetention = last.results ? last.results.retention : 92;
            var finalStar = last.results ? last.results.starModel : 30;
            var finalInfluence = last.results ? last.results.influence : 10;

            var score = Math.round(
                finalOci * 0.35 +
                finalCompliance * 0.25 +
                finalRetention * 0.20 +
                finalStar * 0.15 +
                finalInfluence * 0.05
            );

            var performanceKey = 'perf_needs';
            if (score >= 75) performanceKey = 'perf_excellent';
            else if (score >= 60) performanceKey = 'perf_good';
            else if (score >= 45) performanceKey = 'perf_developing';
            var performance = this._t(performanceKey);

            var insights = [];
            if (finalOci >= 60) insights.push(this._t('ins_oci_high'));
            if (finalOci < 45) insights.push(this._t('ins_oci_low'));
            if (finalCompliance >= 70) insights.push(this._t('ins_comp_high'));
            if (finalCompliance < 50) insights.push(this._t('ins_comp_low'));
            if (finalRetention >= 85) insights.push(this._t('ins_ret_high'));
            if (finalRetention < 80) insights.push(this._t('ins_ret_low'));
            if (finalStar >= 60) insights.push(this._t('ins_star_high'));
            if (finalStar < 40) insights.push(this._t('ins_star_low'));
            if (insights.length === 0) insights.push(this._t('ins_mixed'));

            return {
                overallScore: score,
                oci: finalOci,
                compliance: finalCompliance,
                retention: finalRetention,
                starModel: finalStar,
                influence: finalInfluence,
                performance: performance,
                performanceKey: performanceKey,
                insights: insights
            };
        }

        getHint(state, results) {
            if (state.currentPeriod === 1 && results.ociDelta < 0) {
                return window.mySimulation.t('hint_oci_drop');
            }
            if (state.currentPeriod === 2 && state.domainState.aguirreStatus === 'resigned') {
                return window.mySimulation.t('hint_aguirre_resigned');
            }
            if (state.domainState.starModelAlignment < 35) {
                return window.mySimulation.t('hint_star_low');
            }
            if (state.domainState.employeeRetention < 80) {
                return window.mySimulation.t('hint_retention_low');
            }
            if (results.ociDelta > 10) {
                return window.mySimulation.t('hint_oci_great');
            }
            return null;
        }

