        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = t(round.titleKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.briefingKey);

            var panel = document.getElementById('decisionsPanel');
            if (panel) {
                var html = '';
                for (var i = 0; i < round.decisions.length; i++) {
                    var dec = round.decisions[i];
                    html += '<div class="redmundo-sim-decision-group">';
                    html += '<label for="' + dec.id + 'Select">' + t(dec.labelKey) + '</label>';
                    html += '<select id="' + dec.id + 'Select" class="form-control">';
                    html += '<option value="">-- ' + t('decisions_heading') + ' --</option>';
                    for (var j = 0; j < dec.options.length; j++) {
                        var opt = dec.options[j];
                        html += '<option value="' + opt.value + '">' + t(opt.labelKey) + '</option>';
                    }
                    html += '</select>';
                    html += '<div class="redmundo-sim-hint">' + t(dec.hintKey) + '</div>';
                    html += '</div>';
                }
                panel.innerHTML = html;
            }

            var eventEl = document.getElementById('eventAlert');
            if (eventEl) eventEl.style.display = 'none';
        }

        _showEvents(eventKeys) {
            var eventEl = document.getElementById('eventAlert');
            if (!eventEl || !eventKeys || eventKeys.length === 0) return;
            var t = window.mySimulation.t.bind(window.mySimulation);
            var msgs = eventKeys.map(function(k) { return t(k); });
            eventEl.innerHTML = '<strong>⚡ ' + msgs.join('<br>⚡ ') + '</strong>';
            eventEl.style.display = 'block';
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new RedMundoAdapter(), {
            simulationType: 'red_mundo_ona',
            maxPeriods: 3,
            autoSaveInterval: 30000
        });
    });

})();
